package ltnc.auction.server.net;
import java.net.*; import java.nio.file.Path; import java.util.concurrent.*; import ltnc.auction.server.persistence.AuctionStore; import ltnc.auction.server.service.AuctionManager;
public final class AuctionServer { public static void main(String[] args)throws Exception{int port=Integer.parseInt(System.getenv().getOrDefault("AUCTION_PORT","5050"));Path data=Path.of(System.getenv().getOrDefault("AUCTION_DATA_FILE","server/data/auction-data.ser"));AuctionManager manager=AuctionManager.getInstance();manager.configureStore(new AuctionStore(data));if(manager.listAuctions().isEmpty()){var item=new ltnc.auction.common.model.Electronics("item-1","Tai nghe mẫu","Sản phẩm mẫu để thử client","seller-demo",new java.math.BigDecimal("100000"));manager.addAuction(new ltnc.auction.common.model.Auction("auction-1",item,new java.math.BigDecimal("100000"),new java.math.BigDecimal("10000"),java.time.Instant.now().minusSeconds(60),java.time.Instant.now().plusSeconds(3600)));}ExecutorService pool=Executors.newVirtualThreadPerTaskExecutor();try(ServerSocket server=new ServerSocket(port)){System.out.println("Auction server listening on "+port);while(true){Socket client=server.accept();pool.submit(new ClientHandler(client,manager));}}finally{pool.close();}}
}
